                        [disabled]="$disabled()"
                        [tabindex]="-1"
                        [variant]="checkboxVariant()"
                        [binary]="true"
                        [attr.aria-label]="toggleAllAriaLabel()"
                        [pt]="ptm('pcCheckbox')"
